// The widget platform in the fake host, through a test-only widget (fixtures/widget-platform,
// packed from src/main.ts): a cmux.section/1 card in the three widget sizes that reads the
// system calendar (system_calendar.events, system_calendar.request_access) and emits a scene.
// The sample widgets (clock, weather, calendar, to-do) live in the sample widget repos
// (manaflow-ai/cmux-widget-*) and test themselves there.
//
// The webviews gallery draws recorded widget scenes (webviews/src/apps/scene/fixtures/widget-scenes.json),
// generated by the sample widgets. They are data in the scene op format, not widget source: the last
// test checks that every recorded scene is still a whole batch the scene store can apply.
import { beforeAll, describe, expect, test } from "bun:test"
import { readFileSync } from "node:fs"
import { join } from "node:path"
import { pack } from "../../tools/pack.ts"
import { SchemaValidator } from "../../tools/json-schema.ts"
import { FakeHost, type Op } from "./fake-host.ts"

const hostDir = join(import.meta.dir, "../..")
const root = join(hostDir, "../../..")
const dir = join(import.meta.dir, "fixtures/widget-platform")
const sdk = join(hostDir, "../cmux-extension-sdk/typescript/src/index.ts")
const manifest = JSON.parse(readFileSync(join(dir, "cmux-app.json"), "utf8"))
const SIZES = ["small", "medium", "large"] as const
let built = ""

beforeAll(async () => {
  built = await pack(dir, { sdk })
})

// Monday 2026-11-16 14:05 UTC, read as local time (offset 0).
const AT = Date.UTC(2026, 10, 16, 14, 5)
const HOUR = 3_600_000
const ok = (value: unknown = null) => ({ ok: true, body: { value } })

const ev = (id: string, startH: number) => ({ id, title: id, start: AT + startH * HOUR, end: AT + (startH + 1) * HOUR, allDay: false, calendar: "Work" })
// "ended" is over: never shown. Six upcoming: more than the large size holds.
const EVENTS = [ev("ended", -3), ev("e1", -0.5), ev("e2", 1), ev("e3", 2), ev("e4", 3), ev("e5", 4), ev("e6", 5)]

function host(settings: Record<string, unknown>, access = "granted") {
  const h = new FakeHost(built, { app: { id: manifest.id, version: "1.0.0" }, settings, apiVersion: "1.0.0" })
  h.eval(`Date.now = () => globalThis.__now; Date.prototype.getTimezoneOffset = () => 0; globalThis.__now = ${AT}`)
  let state = access
  h.handlers["system_calendar.events"] = () => ok({ access: state, events: state === "granted" ? EVENTS : [] })
  h.handlers["system_calendar.request_access"] = () => {
    state = "granted"
    return ok({ access: state })
  }
  return h
}

/** The nodes reachable from the root (a removed subtree's descendants stay in FakeHost.tree). */
function live(h: FakeHost, mount = "m") {
  const tree = h.tree(mount)
  const out = new Map<string, { type: string; props: Record<string, unknown>; children: string[] }>()
  const walk = (id: string) => {
    const n = tree.nodes.get(id)
    if (!n) return
    out.set(id, n)
    n.children.forEach(walk)
  }
  walk(tree.root)
  return { root: tree.root, nodes: out }
}

/** Every Text and title on screen, in tree order. */
function texts(h: FakeHost): string[] {
  const out: string[] = []
  for (const n of live(h).nodes.values()) for (const k of ["text", "title"]) if (typeof n.props[k] === "string" && n.props[k]) out.push(n.props[k] as string)
  return out
}

async function mounted(settings: Record<string, unknown>, access = "granted") {
  const h = host(settings, access)
  h.mount("m", manifest.implements["cmux.section/1"].export)
  await h.settle()
  return h
}

/** Checks `ops` is one whole batch: unique creates, children and root naming created nodes. */
function expectWholeBatch(ops: Op[]) {
  const created = new Set<string>()
  for (const op of ops.filter((o) => o.op === "create")) {
    expect(created.has(op.id)).toBe(false)
    expect(typeof op.type).toBe("string")
    created.add(op.id)
  }
  for (const op of ops.filter((o) => o.op === "children")) for (const c of [op.id, ...op.children!]) expect(created.has(c)).toBe(true)
  const roots = ops.filter((o) => o.op === "root")
  expect(roots).toHaveLength(1)
  expect(created.has(roots[0]!.id)).toBe(true)
}

test("the fixture's manifest is a valid v2 widget: a section, the size setting, the calendar scope", () => {
  const schema = new SchemaValidator(JSON.parse(readFileSync(join(hostDir, "schema/v2/cmux-app.schema.json"), "utf8")))
  expect(schema.validate(manifest)).toEqual([])
  expect(manifest.settings.properties.size.enum).toEqual([...SIZES])
  expect(Object.keys(manifest.scopes)).toEqual(["system_calendar:read"])
})

describe("widget sizes", () => {
  for (const [size, shown] of [["small", ["e1"]], ["medium", ["e1", "e2", "e3"]], ["large", ["e1", "e2", "e3", "e4", "e5"]]] as const) {
    test(`${size}: a card that shows ${shown.length} upcoming event(s) and marks its size in the menu`, async () => {
      const h = await mounted({ size })
      expect(texts(h)).toEqual([size.toUpperCase(), ...shown])
      const panel = [...live(h).nodes.values()].find((n) => n.type === "Panel")!
      expect(panel.props.style).toBe("card")
      const menu = panel.props.menu as Array<{ title: string; children: Array<{ title: string }> }>
      expect(menu.map((m) => [m.title, ...m.children.map((c) => c.title)])).toEqual([
        ["Size", ...["Small", "Medium", "Large"].map((t) => (t.toLowerCase() === size ? `✓ ${t}` : t))]
      ])
    })
  }

  test("no size setting falls back to small", async () => {
    expect(texts(await mounted({}))).toEqual(["SMALL", "e1"])
  })
})

describe("system_calendar", () => {
  test("events is read once with the widget's range; it never asks for access on its own", async () => {
    const h = await mounted({ size: "large" }, "notDetermined")
    expect(h.calls.filter((c) => c.name.startsWith("system_calendar.")).map((c) => [c.name, c.params])).toEqual([["system_calendar.events", { days: 7, limit: 5 }]])
    expect(texts(h)).toEqual(["LARGE", "Show my calendar"])
  })

  test("request_access goes out with the tap's gesture, then the events are read again", async () => {
    const h = await mounted({ size: "medium" }, "notDetermined")
    const button = [...live(h).nodes].find(([, n]) => n.type === "Button" && n.props.title === "Show my calendar")![0]
    h.dispatch("m", button, "tap", { gesture: "g1" })
    await h.settle()
    const asks = h.calls.filter((c) => c.name === "system_calendar.request_access")
    expect(asks.map((c) => c.options.gesture)).toEqual(["g1"])
    expect(h.calls.filter((c) => c.name === "system_calendar.events")).toHaveLength(2)
    expect(texts(h)).toEqual(["MEDIUM", "e1", "e2", "e3"])
  })
})

describe("scene output", () => {
  test("each size's first scene is one whole batch rooted at the card", async () => {
    for (const size of SIZES) {
      const h = await mounted({ size })
      const first = h.batches("m")[0]!
      expectWholeBatch(first)
      const rootId = first.find((o) => o.op === "root")!.id
      expect(first.find((o) => o.op === "create" && o.id === rootId)!.type).toBe("Panel")
    }
  })

  test("the gallery's recorded widget scenes are whole batches, each widget in each size", () => {
    const scenes = JSON.parse(readFileSync(join(root, "webviews/src/apps/scene/fixtures/widget-scenes.json"), "utf8")) as Record<string, Op[]>
    expect(Object.keys(scenes).sort()).toEqual(["calendar", "clock", "todo", "weather"].flatMap((w) => SIZES.map((s) => `${w}.${s}`)).sort())
    for (const ops of Object.values(scenes)) expectWholeBatch(ops)
  })
})
